def _coerce(raw, current):
    if isinstance(current, bool):
        return raw.strip().lower() in ('1', 'true', 'yes', 'on')
    if isinstance(current, int):
        return int(raw)
    if isinstance(current, float):
        return float(raw)
    return raw

def _set_path_fixed(cfg, keys, raw):
    node = cfg
    for k in keys[:-1]:
        node[k] = node.get(k) or {}  # Create missing intermediate nodes
        node = node[k]
    leaf = keys[-1]
    node[leaf] = _coerce(raw, node.get(leaf))
    print(f'After: {leaf} = {node[leaf]!r} (type {type(node[leaf]).__name__})')

